package vn.edu.eaut.lab9.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab9.model.*;import vn.edu.eaut.lab9.repository.*;import java.io.*;
@WebServlet("/module") public class ModuleController extends HttpServlet{private final LopHocRepository lop=new LopHocRepository();private final MonHocRepository mon=new MonHocRepository();private final DiemRepository diem=new DiemRepository();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{String m=r.getParameter("m");if("lop".equals(m)){r.setAttribute("data",lop.findAll());r.getRequestDispatcher("/views/lophoc/list.jsp").forward(r,p);}else if("mon".equals(m)){r.setAttribute("data",mon.findAll());r.getRequestDispatcher("/views/monhoc/list.jsp").forward(r,p);}else{r.setAttribute("data",diem.findAll());r.getRequestDispatcher("/views/diem/list.jsp").forward(r,p);}}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{String m=r.getParameter("m");if("lop".equals(m))lop.save(new LopHoc(r.getParameter("tenLop")));else if("mon".equals(m))mon.save(new MonHoc(r.getParameter("maMon"),r.getParameter("tenMon"),Integer.parseInt(r.getParameter("soTinChi"))));else{SinhVien sv=new SinhVienRepository().findById(Integer.parseInt(r.getParameter("sv")));MonHoc mh=mon.findById(Integer.parseInt(r.getParameter("mon")));diem.save(new Diem(sv,mh,Double.parseDouble(r.getParameter("cc")),Double.parseDouble(r.getParameter("gk")),Double.parseDouble(r.getParameter("ck"))));}p.sendRedirect("module?m="+m);}catch(Exception e){p.sendRedirect("?error="+java.net.URLEncoder.encode(e.getMessage(),"UTF-8"));}}}
